pub fn classify(value: f64, s_star: f64) -> RowClass {
    if relative_class(value, s_star) {
        RowClass::RelativeVerified
    } else {
        RowClass::AbsoluteVerified {
            bound_bits: row_bound(value, s_star).to_bits(),
        }
    }
}

fn relative_class(value: f64, s_star: f64) -> bool {
    // V-K seeded fault VK-F17 (§7.3-17): every scaled row relative_verified.
    #[cfg(any(test, feature = "mutation-controls"))]
    if super::seeded::active(super::seeded::Fault::F17) {
        return true;
    }
    let small = f64::from_bits(0x0230_0000_0000_0000); // 2^-988
    !(s_star < small || value.abs() < threshold(s_star))
}

let rows = layout
    .iter()
    .zip(values)
    .map(|(meta, v)| {
        let class = if meta.input_derived {
            RowClass::InputDerived
        } else if let Some(x) = v.value() {
            classify_row(x, scales[meta.body as usize][meta.kind.index()])?
        } else {
            RowClass::Unpublishable
        };

/// The published rows a target is formed from.
fn sources(target: Target) -> Vec<QuantityId> {
    match target {
        Target::Displacement(d) => vec![QuantityId::Displacement(d)],
        Target::Reaction(d) => vec![QuantityId::Reaction(d)],
        Target::Spring { id, component } => vec![QuantityId::SpringAction {
            spring: id,
            component,
        }],
        Target::DirectionalSpring { id, component } => {
            vec![QuantityId::DirectionalSpringAction {
                spring: id,
                component,
            }]
        }
        Target::StructuralZero => vec![],
        Target::Axial(m) | Target::Extension(m) => vec![end(m, true, Component::Ux)],
        Target::Torque(m) | Target::Twist(m) => vec![end(m, true, Component::Rx)],
        Target::BendingEnd { member, j_end } => vec![
            end(member, j_end, Component::Ry),
            end(member, j_end, Component::Rz),
        ],
        Target::BendingStation(s) => vec![
            QuantityId::StationAction {
                station: s,
                component: Component::Ry,
            },
            QuantityId::StationAction {
                station: s,
                component: Component::Rz,
            },
        ],
    }

    let scales = floor::scales(case, model);
    for row in &case.rows {
        let exp = Exact::parse_decimal(&row.expected).unwrap();
        let scale = Exact::parse_decimal(case.scale_of(row)).unwrap();
        let covered = exact::covered(&exp, &scale, floor::row_scale(row, &scales));
        let verdict = match model.resolve(&row.key) {
            Ok(target) => {
                let v = judge(&observe(target, &published, model), &exp, &scale, covered);
                if !covered {
                    not_covered.push(row.key.clone());
                    for id in sources(target) {
                        let restrained = matches!(id, QuantityId::Displacement(d)
                            if model.constraints.contains(&(d.node, d.component.index())));
                        match published.get(&id).map(|r| &r.class) {
                            Some(RowClass::AbsoluteVerified { .. })
                            | Some(RowClass::Unpublishable) => {}
                            Some(RowClass::InputDerived) if restrained => {
                                input_derived_not_covered
                                    .push(format!("{}:{}", case.id, row.key))
                            }
                            other => class_mismatches.push(format!(
                                "{}: {} ({id:?} is {other:?})",
                                case.id, row.key
                            )),
                        }
                    }
                }
                v
            }
            Err(e) => Verdict::Fail(e),
        };
        if let Verdict::Fail(why) = &verdict {
            failures.push(format!("{}: {} ({}) {why}", case.id, row.key, row.expected));
        }
        tally.add(&verdict);
    }
} else if listed && matches!(outcome, CaseOutcome::Unresolved { .. }) {
    for _row in &case.rows {
        tally.add(&Verdict::ExpectedUnresolved);
    }
} else {
    for _row in &case.rows {
        tally.add(&Verdict::Fail(format!("case {label}")));
    }
    failures.push(format!(
        "{}: not selected: {}",
        case.id,
        records::outcome_text(&outcome)
    ));
}
let record = records::case_record(case, &outcome, &tally, &meter);

for case in &cases {
    let run = run_case(case);
    assert!(run.tally.accounted(), "{}: row accounting", case.id);
    total.merge(&run.tally);
    controls.merge(&run.controls);
    failures.extend(run.failures.iter().cloned());
    failures.extend(run.class_mismatches.iter().map(|m| format!("CLASS {m}")));
    if run.not_covered != case.not_covered {
        failures.push(format!(
            "FLOOR {}: not covered {:?}, committed {:?}",
            case.id, run.not_covered, case.not_covered
        ));
    }
    input_derived.extend(run.input_derived_not_covered.iter().cloned());
    *outcomes.entry(run.outcome.clone()).or_default() += 1;
    records.push(run.record);
}
println!("{family}: {total}");
println!("{family}: outcomes {outcomes:?}");
println!(
    "{family}: controls discriminated {}, non-discriminating {}",
    controls.discriminated, controls.non_discriminating
);
for f in &failures {
    println!("{family}: FAILURE {f}");
}
assert!(failures.is_empty(), "{family}: {} failures", failures.len());
assert_eq!(total, pin.tally, "{family}: the report's counts");
let count = |k: &str| outcomes.get(k).copied().unwrap_or(0);
assert_eq!(
    (count("selected"), count("refused"), count("unresolved")),
    pin.outcomes,
    "{family}: outcomes"
);
assert!(
    controls.undiscriminated.is_empty(),
    "{family}: discriminating controls that pass: {:?}",
    controls.undiscriminated
);
assert!(
    controls.unexpectedly_failing.is_empty(),
    "{family}: {:?}",
    controls.unexpectedly_failing
);
assert_eq!(
    (controls.discriminated, controls.non_discriminating),
    (pin.discriminated, pin.non_discriminating),
    "{family}: controls"
);
assert_eq!(
    input_derived, pin.input_derived_not_covered,
    "{family}: not-covered rows published as input-derived"
);
let (_, file) = FAMILY_FILES.iter().find(|(f, _)| *f == family).unwrap();
let path = crate_dir()
    .join("observations/kernel_lane")
    .join(file.replace(".jsonl", ".json"));
let committed =
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
assert!(
    committed == family_file(&records),
    "{family}: the per-case records differ from {} (regenerate only by decision: \
     cargo run --release --example vk_records -- --write {family})",
    path.display()
);

